def decide(recipient_reputation, round_num, my_history):
    # Use recent cooperation history (last 5 rounds) to set threshold
    recent = my_history[-5:] if len(my_history) >= 5 else my_history
    if len(recent) == 0:
        coop_rate = 0.5  # neutral default
    else:
        coop_count = sum(1 for entry in recent if entry['action'] == 'cooperate')
